document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function s(n){return`${n.toFixed(1)}%`}function e(n,s,e,i="info"){return`\n      <div class="insight-card ${i}">\n        <h6>${n}</h6>\n        <div class="metric-value">${s}</div>\n        <div class="metric-subtitle">${e}</div>\n      </div>\n    `}const i=document.getElementById("vending-form"),t=document.getElementById("vending-result");i&&i.addEventListener("submit",function(i){i.preventDefault();const a=parseInt(document.getElementById("machines").value),o=parseFloat(document.getElementById("machine-cost").value),r=parseFloat(document.getElementById("installation-cost").value),l=parseFloat(document.getElementById("initial-stock").value),d=parseFloat(document.getElementById("permits").value),c=parseFloat(document.getElementById("daily-sales").value),p=parseFloat(document.getElementById("avg-price").value),v=parseFloat(document.getElementById("cost-percentage").value),u=parseFloat(document.getElementById("working-days").value),g=parseFloat(document.getElementById("location-rent").value),m=parseFloat(document.getElementById("maintenance").value),h=parseFloat(document.getElementById("transport").value),$=parseFloat(document.getElementById("other-costs").value);if(a<=0||c<=0||p<=0)return t.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const b=a*(o+r+l)+d,f=c*p,w=f*u,y=w*a,k=y*(v/100),I=y-k,E=g*a,P=m*a,F=E+P+h+$,M=I-F,B=12*M,x=I/y*100,D=M/y*100,L=b/B,S=B/b*100,O=w,R=M/a,T=p;let A="info";M<0?A="warning":D>25&&(A="success");let C="info";S<20?C="warning":S>40&&(C="success");let z="info";L>3?z="warning":L<=2&&(z="success"),t.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🏪 Vending Machine Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${e("💰 Total Investment",n(b),`${a} machines`,"info")}\n            ${e("📈 Monthly Profit",n(M),`Margin: ${s(D)}`,A)}\n            ${e("⏱️ Payback Period",`${L.toFixed(1)} years`,`ROI: ${s(S)}`,z)}\n            ${e("🏪 Profit per Machine",n(R),"Per month",A)}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Equipment (${a} machines × ${n(o)})</span>\n                  <span>${n(a*o)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Installation & setup</span>\n                  <span>${n(a*r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Initial inventory</span>\n                  <span>${n(a*l)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Permits & licenses</span>\n                  <span>${n(d)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(b)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Monthly Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Daily sales (${c} × ${n(p)})</span>\n                  <span>${n(f)}/machine</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Monthly revenue (${u} days)</span>\n                  <span>${n(w)}/machine</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Gross revenue (${a} machines)</span>\n                  <span>${n(y)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Cost of goods sold (${s(v)})</span>\n                  <span>-${n(k)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Gross Profit</strong></span>\n                  <span><strong>${n(I)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Location fees (${n(g)} × ${a})</span>\n                  <span>${n(E)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Maintenance & repairs</span>\n                  <span>${n(P)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Transportation & restocking</span>\n                  <span>${n(h)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Other operating expenses</span>\n                  <span>${n($)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Operating Expenses</strong></span>\n                  <span><strong>${n(F)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>🔄 Sales Efficiency</h6>\n              <div class="metric-subtitle">\n                Revenue per machine: <strong>${n(O)}/month</strong><br>\n                Daily sales volume: <strong>${c} units</strong><br>\n                Average transaction: <strong>${n(T)}</strong>\n              </div>\n            </div>\n            <div class="insight-card ${x>40?"success":"info"}">\n              <h6>📊 Profitability Metrics</h6>\n              <div class="metric-subtitle">\n                Gross margin: <strong>${s(x)}</strong><br>\n                Net margin: <strong>${s(D)}</strong><br>\n                Product cost: <strong>${s(v)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${M>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(B)}</strong><br>\n                Weekly profit: <strong>${n(B/52)}</strong><br>\n                Daily profit: <strong>${n(B/365)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>💡 Scaling Potential</h6>\n              <div class="metric-subtitle">\n                Profit per machine: <strong>${n(R)}/month</strong><br>\n                With 10 machines: <strong>${n(10*R)}/month</strong><br>\n                Potential ROI: <strong>${s(S)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${D<15?"<li>⚠️ Low profitability. Consider raising prices or reducing product costs.</li>":""}\n              ${c<30?"<li>📍 Low sales volume. Improve locations or expand product variety.</li>":""}\n              ${L>3?"<li>⏰ Long payback period. Optimize startup costs or increase sales.</li>":""}\n              ${c>70?"<li>✅ High sales volume! Consider installing additional machines.</li>":""}\n              ${D>25?"<li>🎉 Excellent profitability! Scale your business more aggressively.</li>":""}\n              <li>🏢 Target high-traffic locations: offices, schools, hospitals for stable revenue.</li>\n              <li>💳 Implement cashless payments to increase sales by 20-30%.</li>\n              <li>📊 Analyze sales data to optimize product mix and pricing.</li>\n              <li>🤝 Negotiate long-term placement contracts for location stability.</li>\n              <li>🛠️ Maintain regular service schedules to minimize downtime.</li>\n              <li>📈 Test different pricing strategies and product assortments.</li>\n              <li>🎯 Research customer preferences specific to each location.</li>\n              <li>📱 Use telemetry for remote inventory monitoring and route optimization.</li>\n              <li>🌟 Focus on popular, high-margin products for maximum profitability.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.vendingBusinessData={"Number of Machines":a,"Total Investment ($)":b,"Monthly Revenue ($)":y,"Monthly Expenses ($)":F+k,"Monthly Profit ($)":M,"Annual Profit ($)":B,"Gross Margin (%)":x,"Net Margin (%)":D,"Annual ROI (%)":S,"Payback Period (years)":L,"Daily Sales (units)":c,"Average Product Price ($)":p,"Profit per Machine ($)":R}}),window.downloadCSV=function(){if(!window.vendingBusinessData)return;const n=Object.entries(window.vendingBusinessData).map(([n,s])=>`"${n}","${"number"==typeof s?s.toFixed(2):s}"`).join("\n"),s=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),e=document.createElement("a");e.href=URL.createObjectURL(s),e.download="vending-business-plan.csv",e.click()}});